    expected_aud = server_uri.get(proposed_call["server"])
    if proposed_call.get("jwt_aud") != expected_aud:
        return {"allow": False, "reason": "jwt_aud mismatch"}

    # Clause 1: Exfiltration to less-trusted server
    proposed_trust = server_trust.get(proposed_call["server"], "")
    if proposed_trust in ("untrusted_third_party", "untrusted_external"):
        # Collect qualifying strings from privileged server outputs
        privileged_trusts = {"privileged_internal", "privileged_cloud", "privileged_secrets", "privileged_financial", "privileged_local"}
