            if server_trust.get(srv) in privileged_trusts:
                output = entry.get("output", {})
                def extract_strings(obj):
                    if isinstance(obj, str) and len(obj) >= 4:
                        tainted_strings.add(obj)
                    elif isinstance(obj, dict):
                        for v in obj.values():
                            extract_strings(v)
                    elif isinstance(obj, list):
                        for v in obj:
